import { test, expect, type Page } from '@playwright/test';
import { mockDesktop } from './mockDesktop';
import { readFileSync } from 'node:fs';

// Method IDs are read from the fixed CLI output, never generated by hand.
const binding = readFileSync(new URL('../bindings/cyrene-launcher/internal/news-service/newsservice.ts',import.meta.url),'utf8');
const method = (name: string) => Number(binding.split(`export function ${name}(`)[1].match(/ByID\((\d+)/)![1]);
const openID=method('OpenNewsURL'), imageID=method('GetNewsImage');
const id='f48c7f6b-3a9b-4fba-a7e9-66077aa5c4d8';
const article=`https://register.bassaps.com/announcements#${id}`;
const raster='data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+j1ioAAAAASUVORK5CYII=';
const item={id,title:'News fixture',intro:'<b>literal text</b>',url:article,image:`https://register.bassaps.com/api/files/${id}`,time:'2026-11-11',timestamp:1794418925,type:'notice',pinned:true};

async function setup(page: Page, raw=article, failOpen=false) {
  await mockDesktop(page,true,[{...item,url:raw}]);
  const opened: unknown[][]=[];
  const generic: unknown[]=[];
  const external: string[]=[];
  await page.addInitScript(()=>{ Object.assign(window,{newsWindowOpens:0}); window.open=()=>{ (window as unknown as {newsWindowOpens:number}).newsWindowOpens++;return null; }; });
  for (const pattern of ['https://fixture.invalid/**','https://register.bassaps.com/api/files/**','https://fastcdn.hoyoverse.com/**']) await page.route(pattern,route=>{external.push(route.request().url());return route.abort();});
  await page.route('**/wails/runtime**',route=>{
    const req=route.request(),url=new URL(req.url());
    const body=req.method()==='POST'?req.postDataJSON():{object:Number(url.searchParams.get('object')),args:JSON.parse(url.searchParams.get('args')||'{}')};
    if(body.object!==0)return route.fallback();
    if(body.args.methodID===openID){opened.push(body.args.args);return route.fulfill({json:[!failOpen,failOpen?'news_link_open_failed':'']});}
    if(body.args.methodID===imageID)return route.fulfill({json:[true,raster,'']});
    if(body.args.methodID===1132232877){generic.push(body.args.args);return route.fulfill({json:[true,'']});}
    if(body.args.methodID===1638005996)return route.fulfill({json:[true,[{...item,id:'official',title:'Official fixture',url:'https://hoyo.link/461DNURXG',image:'https://fastcdn.hoyoverse.com/static-resource-v2/2026/11/12/cover.png',pinned:false}],'']});
    return route.fallback();
  });
  return {opened,generic,external};
}

for(const value of ['javascript:void(0)','file:///C:/BASSAPS-REVIEW-NONEXISTENT.txt','data:text/plain,fixture','https://fixture.invalid/review']) {
  test(`unsafe review URL cannot leave Home/news: ${value.split(':')[0]}`,async({page})=>{
    const calls=await setup(page,value);
    await page.goto('/');
    await expect(page.getByRole('button',{name:/News fixture/})).toBeDisabled();
    await page.goto('/news');await page.getByRole('button',{name:'サーバー',exact:true}).click();
    const heading=page.getByRole('heading',{name:'News fixture'});
    await heading.click();
    await expect(page.getByText('<b>literal text</b>',{exact:true})).toBeVisible();
    expect(calls.opened).toEqual([]);expect(calls.generic).toEqual([]);expect(calls.external).toEqual([]);
    expect(await page.evaluate(()=>(window as unknown as {newsWindowOpens:number}).newsWindowOpens)).toBe(0);
  });
}

test('Home and both news sources use their validated Go method and inline raster',async({page})=>{
  const calls=await setup(page);
  await page.goto('/');await page.getByRole('button',{name:/News fixture/}).click();
  expect(calls.opened).toEqual([['register',id,article]]);
  await page.goto('/news');await page.getByRole('heading',{name:'Official fixture'}).click();
  await expect(page.getByRole('img',{name:'Official fixture'})).toHaveAttribute('src',raster);
  await page.getByRole('button',{name:'サーバー',exact:true}).click();
  await expect(page.getByRole('img',{name:'News fixture'})).toHaveAttribute('src',raster);
  await page.getByRole('heading',{name:'News fixture'}).click();
  expect(calls.opened).toEqual([['register',id,article],['official','official','https://hoyo.link/461DNURXG'],['register',id,article]]);
  expect(calls.generic).toEqual([]);expect(calls.external).toEqual([]);
  expect(await page.evaluate(()=>JSON.parse(localStorage.getItem('news-storage')!).state.lastReadServerTimestamp)).toBe(item.timestamp);
});

test('invalid image is a placeholder without fetch or data navigation',async({page})=>{
  const calls=await setup(page);
  await page.route('**/wails/runtime**',route=>{
    const body=route.request().postDataJSON();
    if(body.object===0&&body.args.methodID===3670222014)return route.fulfill({json:[true,[{...item,image:'https://fixture.invalid/unsafe.svg'}],'']});
    return route.fallback();
  });
  await page.goto('/news');await page.getByRole('button',{name:'サーバー',exact:true}).click();
  await expect(page.getByRole('heading',{name:'News fixture'})).toBeVisible();
  await expect(page.getByRole('img',{name:'News fixture'})).toHaveCount(0);
  expect(calls.external).toEqual([]);
});

test('OS failure is visible and never falls back to window.open',async({page})=>{
  const calls=await setup(page,article,true);
  await page.goto('/');await page.getByRole('button',{name:/News fixture/}).click();
  await expect(page.getByText('リンクを開けませんでした。',{exact:true})).toBeVisible();
  expect(calls.opened).toHaveLength(1);expect(calls.generic).toEqual([]);
  expect(await page.evaluate(()=>(window as unknown as {newsWindowOpens:number}).newsWindowOpens)).toBe(0);
});

test('HTML-like article title remains text',async({page})=>{
  await setup(page);
  await page.route('**/wails/runtime**',route=>{
    const body=route.request().postDataJSON();
    if(body.object===0&&body.args.methodID===3670222014)return route.fulfill({json:[true,[{...item,title:'<b>literal title</b>'}],'']});
    return route.fallback();
  });
  await page.goto('/news');await page.getByRole('button',{name:'サーバー',exact:true}).click();
  const title=page.getByRole('heading',{name:'<b>literal title</b>'});
  await expect(title).toBeVisible();await expect(title.locator('b')).toHaveCount(0);
});
